type SpriteSt = "wait" | "ok" | "bad";
let spriteState: SpriteSt = "wait";
let spriteStarted = false;
let spriteSrc: CanvasImageSource | null = null;
const spriteSubs: ((v: SpriteSt) => void)[] = [];
// Decodes one embedded AVIF. createImageBitmap(Blob) first: it fetches nothing, so the canvas CSP cannot block it.
// An <img> with a data: URI is only the fallback, and every step has a timeout so icons can never hang blank.
function decodeSprite(b64: string, ms: number): Promise<CanvasImageSource> {
  return new Promise((res, rej) => {
    let settled = false;
    const ok = (v: CanvasImageSource) => { if (!settled) { settled = true; res(v); } };
    const no = () => { if (!settled) { settled = true; rej(new Error("sprite decode failed")); } };
    setTimeout(no, ms);
    const viaImg = () => {
      try {
        const im = new Image();
        im.onload = () => ok(im);
        im.onerror = no;
        im.src = `data:image/avif;base64,${b64}`;
      } catch (e) {
        no();
      }
    };
    try {
      if (typeof createImageBitmap !== "function") { viaImg(); return; }
      const bin = atob(b64);
      const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      createImageBitmap(new Blob([bytes], { type: "image/avif" })).then(ok, viaImg);
    } catch (e) {
      viaImg();
    }
  });
}
function loadSprite(): void {
  spriteStarted = true;
  const finish = (st: SpriteSt) => { spriteState = st; spriteSubs.splice(0).forEach((f) => f(st)); };
  const compose = (main: CanvasImageSource, extra: (CanvasImageSource | null)[]) => {
    spriteSrc = main;
    try {
      if ((extra[0] || extra[1]) && typeof document !== "undefined") {
        const c = document.createElement("canvas");
        c.width = SPRITE_COLS * SPRITE_PX;
        c.height = Math.ceil((SPRITE_C_START + SPRITE_C_NAMES.length) / SPRITE_COLS) * SPRITE_PX;
        const ctx = c.getContext("2d");
        if (ctx) {
          ctx.drawImage(main, 0, 0);
          if (extra[0]) ctx.drawImage(extra[0], 0, Math.floor(SPRITE_B_START / SPRITE_COLS) * SPRITE_PX);
          if (extra[1]) ctx.drawImage(extra[1], 0, Math.floor(SPRITE_C_START / SPRITE_COLS) * SPRITE_PX);
          spriteSrc = c;
        }
      }
    } catch (e) {
      spriteSrc = main;
    }
    finish("ok");
  };
  const opt = (b64: string) => decodeSprite(b64, 4000).then((x: CanvasImageSource) => x, () => null);
  decodeSprite(SPRITE_PARTS.join(""), 8000).then(
    (main) => Promise.all([opt(SPRITE_B), opt(SPRITE_C_PARTS.join(""))]).then((extra: (CanvasImageSource | null)[]) => compose(main, extra)),
    () => finish("bad"),
  );
}
function useSprite(): SpriteSt {
  const [st, setSt] = useState<SpriteSt>(spriteState);
  useEffect(() => {
    if (spriteState !== "wait") { setSt(spriteState); return; }
    spriteSubs.push(setSt);
    if (!spriteStarted) loadSprite();
  }, []);
  return st;
}
