type Macro = { title: string; icon: string; spec: "aff" | "demo" | "both" | "enh"; where: string; code: string; does: string; tag?: "NEW" | "FIXED"; lvl?: number; src: string; url?: string; flag?: string };
const WFDB_AFF = WF_DATA.macros.WFDB_AFF;
const WFDB_DEMO = WF_DATA.macros.WFDB_DEMO;
const WFDB_ENH = WF_DATA.macros.WFDB_ENH;
const MACROS: Macro[] = WF_DATA.macros.MACROS;

function MacroCard({ m }: { m: Macro }) {
  const [copied, setCopied] = useState<string>("");
  const [open, setOpen] = useState<boolean>(false);
  const len = m.code.length;
  const over = len > 255;
  const tone = m.spec === "enh" ? SHAMAN : WARLOCK;
  const doCopy = () => {
    const done = () => { setCopied("Copied"); setTimeout(() => setCopied(""), 1400); };
    const fail = () => { setCopied("Select the text and copy"); setTimeout(() => setCopied(""), 2200); };
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(m.code).then(done, fail);
      else fail();
    } catch (e: unknown) { fail(); }
  };
  return (
    <div className="wf-card" style={{ position: "relative", borderRadius: 10, padding: 12, border: `1px solid ${m.tag === "NEW" ? FEL : m.tag === "FIXED" ? ORANGE : "#4a3d22"}`, background: "linear-gradient(180deg, #1a1712, #0d0c0a)", boxShadow: "inset 0 1px 0 rgba(255,255,255,.05)" }}>
      <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
        <Icon icon={m.icon} size={40} ring={tone} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: SERIF, color: "#fff", fontSize: 15, display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
            {m.title}
            {m.tag ? <span className={m.tag === "NEW" ? "wf-new" : undefined} style={{ fontSize: 10, fontWeight: 800, padding: "1px 6px", borderRadius: 4, background: m.tag === "NEW" ? FEL : ORANGE, color: "#000", fontFamily: "inherit" }}>{m.tag}</span> : null}
            {m.lvl ? <span style={{ fontSize: 10, padding: "1px 6px", borderRadius: 4, border: `1px solid ${GOLD}`, color: GOLD_HI }}>Lv {m.lvl}</span> : null}
            {m.lvl && m.lvl > 30 ? <PreTag mark="guide" small src={`${m.src}, read Oct 30`} /> : null}
          </div>
          <div style={{ fontSize: 11, color: MUTED }}>{m.where}</div>
        </div>
      </div>
      <pre style={{ margin: "10px 0 0", padding: 10, borderRadius: 6, background: "#07070a", color: "#e8d9a8", border: "1px solid #3a3020", fontFamily: "ui-monospace, Menlo, Consolas, monospace", fontSize: 12, lineHeight: 1.45, whiteSpace: "pre-wrap", wordBreak: "break-word", userSelect: "all" }}>{m.code}</pre>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 8 }}>
        <button type="button" className="wf-btn" onClick={doCopy} style={{ padding: "4px 12px", borderRadius: 6, border: `1px solid ${GOLD}`, background: "linear-gradient(180deg, #7a1a12, #3d0c08)", color: GOLD_HI, fontSize: 12, fontWeight: 700 }}>{copied || "Copy"}</button>
        <button type="button" className="wf-btn" onClick={() => setOpen(!open)} style={{ padding: "4px 10px", borderRadius: 6, border: "1px solid #4a3d22", background: open ? "#2a2316" : "transparent", color: INK, fontSize: 12 }}>{open ? "Hide" : "What it does"}</button>
        <span style={{ marginLeft: "auto", fontSize: 11, color: over ? "#ff4040" : len > 230 ? ORANGE : MUTED }}>{len}/255</span>
      </div>
      {open ? (
        <div className="wf-pop" style={{ marginTop: 8, padding: 8, borderRadius: 6, background: "rgba(8,9,20,.9)", border: "1px solid #6b5a33", fontSize: 12, color: "#fff", lineHeight: 1.45 }}>
          {m.does}
          {m.flag ? <div style={{ color: ORANGE, marginTop: 4 }}>⚠ {m.flag}</div> : null}
          <div style={{ color: MUTED, marginTop: 4 }}>Source: {m.url ? <a href={m.url} target="_blank" rel="noreferrer" style={{ color: GOLD_HI }}>{m.src}</a> : m.src}</div>
        </div>
      ) : null}
    </div>
  );
}

function MacroBook({ lvV, lvC }: { lvV: number; lvC: number }) {
  const [f, setF] = useState<string>("all");
  const [showAll, setShowAll] = useState<boolean>(false);
  const lvOf = (m: Macro) => m.spec === "enh" ? lvV : lvC;
  const locked = (m: Macro) => !!m.lvl && m.lvl > lvOf(m);
  const tabs: [string, string, string][] = [["all", "All", "inv_misc_book_09"], ["aff", "Affliction", "spell_shadow_deathcoil"], ["demo", "Demonology", "spell_shadow_metamorphosis"], ["enh", "Enhancement", "spell_nature_lightningshield"], ["new", "New + fixed", "spell_holy_borrowedtime"]];
  const all = MACROS.filter((m: Macro) => f === "all" ? true : f === "new" ? !!m.tag : f === "enh" ? m.spec === "enh" : m.spec === f || m.spec === "both");
  const ordered = [...all.filter((m: Macro) => m.spec !== "enh"), ...all.filter((m: Macro) => m.spec === "enh")];
  const list = showAll ? ordered : ordered.filter((m: Macro) => !locked(m));
  const hidden = all.length - list.length;
  return (
    <Frame accent={GOLD} title="Macro book" icon="inv_misc_book_09" right={<span style={{ fontSize: 12, color: MUTED }}>{list.length} shown{hidden ? ` · ${hidden} above your level` : ""}</span>}>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 12 }}>
        {tabs.map((t: [string, string, string]) => (
          <button key={t[0]} type="button" className="wf-tab" onClick={() => setF(t[0])} style={{ display: "flex", alignItems: "center", gap: 6, padding: "4px 10px 4px 4px", borderRadius: 8, border: `1px solid ${f === t[0] ? GOLD : "#4a3d22"}`, background: f === t[0] ? "rgba(245,215,122,.15)" : "#14110d", color: f === t[0] ? "#fff" : MUTED, fontSize: 13 }}>
            <Icon icon={t[2]} size={24} />{t[1]}
          </button>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))", gap: 10 }}>
        {list.map((m: Macro) => locked(m) ? <div key={m.title} style={{ opacity: 0.45, filter: "grayscale(.8)" }}><MacroCard m={m} /></div> : <MacroCard key={m.title} m={m} />)}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 10, flexWrap: "wrap", fontSize: 12, color: MUTED }}>
        <span>Macros with a Lv tag above the character's level (Vorgash {lvV} for Enhancement, Corvin {lvC} for Warlock) are {showAll ? "grayed" : "hidden"}. Untagged macros always show.</span>
        <button type="button" className="wf-btn" onClick={() => setShowAll(!showAll)} style={{ padding: "2px 10px", borderRadius: 999, border: `1px solid ${showAll ? GOLD : "#4a3d22"}`, background: showAll ? "rgba(245,215,122,.15)" : "transparent", color: showAll ? GOLD_HI : INK, fontSize: 12 }}>{showAll ? "Hide locked" : "Show all"}</button>
      </div>
      <div style={{ fontSize: 11, color: MUTED, marginTop: 10 }}>Syntax checked against Forever's macro pages on wowfdb (read Oct 30). Every wowfdb macro is marked Untested there, and none of these have been run in the Forever client yet.</div>
    </Frame>
  );
}

const SHAM_GEAR: string[][] = WF_DATA.gear.SHAM_GEAR;
const LOCK_GEAR: string[][] = WF_DATA.gear.LOCK_GEAR;

// ===== Gear character sheet: built from the SHAM_GEAR / LOCK_GEAR rows above (levels, items, sources unchanged).
// Item icon and quality: Wowhead's WoW Forever item database (exact-name matches, read Oct 30 2026). Icons live in sprite C.
const QUALITY: Record<number, [string, string]> = WF_DATA.gear.QUALITY;
const ITEM_INFO: Record<string, [string, number]> = WF_DATA.gear.ITEM_INFO;
type GPick = { id: string; lv: string; from: number; to: number; name: string; item: string; alt?: string; src: string };
type GSlot = { slot: string; picks: GPick[]; none?: string };
function lvRange(lv: string): [number, number] {
  const m = lv.match(/^(\d+)\s*[–-]\s*(\d+)$/);
  if (m) return [Number(m[1]), Number(m[2])];
  const s = lv.match(/^(\d+)s$/);
  if (s) return [Number(s[1]), Number(s[1]) + 9];
  const p = lv.match(/^(\d+)\+?$/);
  if (p) return [Number(p[1]), 60];
  return [1, 60];
}
function gp(rows: string[][], pre: string, i: number, o?: { id?: string; lv?: string; name?: string; item?: string; alt?: string; src?: string }): GPick {
  const r = rows[i];
  const lv = o?.lv ?? r[0];
  const [from, to] = lvRange(lv);
  const name = o?.name ?? r[2];
  return { id: o?.id ?? `${pre}${i}`, lv, from, to, name, item: o?.item ?? name, alt: o?.alt, src: o?.src ?? r[3] };
}
const G_NONE = (slot: string, none?: string): GSlot => ({ slot, picks: [], none: none ?? "not in notes" });
const GEAR_SHEETS: Record<string, { left: GSlot[]; right: GSlot[]; bottom: GSlot[] }> = WF_DATA.gear.GEAR_SHEETS;
// Ticks added for the sheet (second ring, off-hands, the later item of "A → B" rows). Appended to the end of CHECK_IDS.
const GEAR_EXTRA_IDS: string[] = WF_DATA.gear.GEAR_EXTRA_IDS;
function gearPick(s: GSlot, lv: number): { p: GPick | null; i: number; state: "now" | "soon" | "past" } {
  if (!s.picks.length) return { p: null, i: -1, state: "now" };
  let i = -1;
  for (let k = 0; k < s.picks.length; k++) if (s.picks[k].from <= lv) i = k;
  if (i < 0) return { p: s.picks[0], i: 0, state: "soon" };
  const p = s.picks[i];
  return { p, i, state: lv <= p.to ? "now" : "past" };
}
// Gear past 30 (rules.md SPLIT, clarified Oct 31 9:32 AM): notes picks that start at 30 or later and run past 30 (not exact level-30 items) stay, tagged NOTES_PRE. The pre-launch label is only for past-30 slots the notes don't fill.
function prePick(p: GPick): boolean { return p.from > 30 || (p.from === 30 && p.to > 30 && p.lv.trim() !== "30"); }
function GearSlot({ s, lv, ck, toggle, sel, onSel, mirror }: { s: GSlot; lv: number; ck: Record<string, boolean>; toggle: (id: string) => void; sel: boolean; onSel: (slot: string) => void; mirror?: boolean }) {
  const { p, i, state } = gearPick(s, lv);
  const label = <div style={{ fontSize: 9, letterSpacing: ".12em", textTransform: "uppercase", color: MUTED }}>{s.slot}</div>;
  if (!p) {
    return (
      <div style={{ display: "flex", flexDirection: mirror ? "row-reverse" : "row", gap: 8, alignItems: "center", padding: 6, borderRadius: 6, border: "1px dashed #4a3d22", background: "rgba(0,0,0,.25)", textAlign: mirror ? "right" : "left", minHeight: 48 }}>
        <span style={{ flex: "none", width: 36, height: 36, borderRadius: 4, border: "1px dashed #6b5a33", background: "repeating-linear-gradient(45deg, #15110d 0 6px, #1c1712 6px 12px)" }} />
        <div style={{ minWidth: 0 }}>{label}<div style={{ fontSize: 11, color: MUTED, fontStyle: "italic" }}>{s.none}</div>{lv > 30 ? <span className="wf-pre wf-pre-sm" style={{ marginTop: 2 }}>{PRE_LABEL}</span> : null}</div>
      </div>
    );
  }
  const info = ITEM_INFO[p.item];
  const q = info ? QUALITY[info[1]] : [GOLD, "Quality not listed"];
  const alt = p.alt ? ITEM_INFO[p.alt] : undefined;
  const got = !!ck[p.id];
  const chase = state === "now" && !got;
  return (
    <div className={chase ? "wf-glow" : undefined} role="button" tabIndex={0} onClick={() => onSel(s.slot)} style={{ position: "relative", display: "flex", flexDirection: mirror ? "row-reverse" : "row", gap: 8, alignItems: "flex-start", padding: 6, borderRadius: 6, border: `1px solid ${chase ? ORANGE : sel ? GOLD_HI : "#3a3020"}`, background: chase ? "linear-gradient(180deg, rgba(255,128,0,.14), rgba(0,0,0,.35))" : "rgba(0,0,0,.35)", textAlign: mirror ? "right" : "left", cursor: s.picks.length > 1 ? "pointer" : "default", opacity: state === "soon" ? 0.78 : 1 }}>
      <div style={{ flex: "none", display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}>
        <span style={{ display: "block", borderRadius: 5, boxShadow: `0 0 0 1px #000, 0 0 8px ${q[0]}88` }}><Icon icon={info ? info[0] : ""} size={36} ring={q[0]} name={p.name} tip={`${q[1]} · ${p.src}`} /></span>
        <span onClick={(e: { stopPropagation: () => void }) => e.stopPropagation()} style={{ display: "flex", alignItems: "center", gap: 2, fontSize: 9, color: got ? FEL : MUTED }}><TickBox on={got} onClick={() => toggle(p.id)} small color={q[0]} />Got</span>
      </div>
      <div style={{ minWidth: 0, flex: 1 }}>
        <div style={{ display: "flex", flexDirection: mirror ? "row-reverse" : "row", flexWrap: "wrap", gap: 4, alignItems: "center" }}>
          {label}
          {chase ? <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: ".08em", padding: "0 5px", borderRadius: 3, background: ORANGE, color: "#1a0d00" }}>CHASE</span> : null}
          {s.picks.length > 1 ? <span style={{ fontSize: 9, color: GOLD }}>{i + 1}/{s.picks.length}</span> : null}
        </div>
        <div style={{ fontSize: 12, fontWeight: 600, lineHeight: 1.25, color: q[0], textShadow: "0 1px 0 #000", overflowWrap: "anywhere" }}>{p.name}{p.alt ? <span style={{ color: MUTED, fontWeight: 400 }}> or <span style={{ color: alt ? QUALITY[alt[1]][0] : INK, fontWeight: 600 }}>{p.alt}</span></span> : null}</div>
        <div style={{ fontSize: 10, color: MUTED, lineHeight: 1.3, overflowWrap: "anywhere" }}>{p.src}</div>
        <div style={{ fontSize: 10, color: state === "soon" ? ORANGE : INK }}>Lv {p.lv}{state === "soon" ? ` · from ${p.from}` : state === "past" ? " · past its range" : ""}</div>
        {prePick(p) ? <span className="wf-mark wf-mark-notes" style={{ fontSize: 9 }}>{NOTES_PRE}</span> : state === "past" && lv > 30 ? <span className="wf-pre wf-pre-sm" title="Your notes have no pick for this slot past 30">{PRE_LABEL}</span> : null}
      </div>
    </div>
  );
}
function GearSheet({ who, lv, ck, toggle }: { who: "sham" | "lock"; lv: number; ck: Record<string, boolean>; toggle: (id: string) => void }) {
  const sh = GEAR_SHEETS[who];
  const c = who === "sham" ? CHARS[0] : CHARS[1];
  const all = [...sh.left, ...sh.right, ...sh.bottom];
  const picks = all.flatMap((s: GSlot) => s.picks);
  const gotN = picks.filter((p: GPick) => !!ck[p.id]).length;
  const chasing = all.filter((s: GSlot) => { const r = gearPick(s, lv); return !!r.p && r.state === "now" && !ck[r.p.id]; });
  const multi = all.filter((s: GSlot) => s.picks.length > 1);
  const [sel, setSel] = useState<string>("");
  const cur = multi.find((s: GSlot) => s.slot === sel) ?? chasing.find((s: GSlot) => s.picks.length > 1) ?? multi[0];
  const onSel = (slot: string) => setSel(slot);
  const slotEl = (s: GSlot, mirror?: boolean) => <GearSlot key={s.slot} s={s} lv={lv} ck={ck} toggle={toggle} sel={!!cur && cur.slot === s.slot} onSel={onSel} mirror={mirror} />;
  return (
    <div className="wf-sheetwrap" style={{ margin: "10px 0 14px" }}>
      <Frame accent={c.color} title={`${c.name.split(" ")[0]}: character sheet`} icon={c.classIcon} right={<span style={{ fontSize: 12, color: c.color, fontFamily: SERIF }}>Level {lv}</span>}>
        <div className="wf-sheet">
          <div className="wf-sheet-l">{sh.left.map((s: GSlot) => slotEl(s))}</div>
          <div className="wf-sheet-c" style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 8, padding: "14px 8px", borderRadius: 10, border: "1px solid #3a3020", background: `radial-gradient(60% 45% at 50% 38%, ${c.color}55, transparent 70%), radial-gradient(90% 70% at 50% 100%, rgba(0,0,0,.6), transparent), linear-gradient(180deg, #1d1812, #0b0907)`, textAlign: "center" }}>
            <span className="wf-pulse" style={{ display: "block", borderRadius: 12, boxShadow: `0 0 24px ${c.color}aa, 0 0 0 2px ${GOLD}` }}><Icon icon={c.classIcon} size={84} ring={c.color} /></span>
            <div style={{ fontFamily: SERIF, fontSize: 16, color: GOLD_HI, textShadow: "0 1px 0 #000" }}>{c.name}</div>
            <div style={{ fontSize: 11, color: INK }}>{c.line}</div>
            <div style={{ fontSize: 12, color: "#fff" }}>Got <b style={{ color: FEL }}>{gotN}</b> / {picks.length} items</div>
            <div style={{ fontSize: 11, color: MUTED }}>{chasing.length ? <span><span style={{ color: ORANGE, fontWeight: 700 }}>{chasing.length} to chase</span> at level {lv}</span> : `Nothing to chase at level ${lv}`}</div>
            <div style={{ display: "flex", gap: 8, justifyContent: "center", flexWrap: "wrap", fontSize: 10 }}>
              {[2, 3].map((n: number) => <span key={n} style={{ color: QUALITY[n][0] }}>■ {QUALITY[n][1]}</span>)}
            </div>
            <div style={{ fontSize: 10, color: MUTED, lineHeight: 1.35 }}>Glowing slots are the chase item for this level. Tap a slot with 2+ items to see its upgrade path below.</div>
          </div>
          <div className="wf-sheet-r">{sh.right.map((s: GSlot) => slotEl(s, true))}</div>
          <div className="wf-sheet-b">{sh.bottom.map((s: GSlot) => slotEl(s))}</div>
        </div>
        {cur ? (
          <div className="wf-pop" key={`${who}-${cur.slot}`} style={{ marginTop: 12, padding: 10, borderRadius: 8, border: "1px solid #3a3020", background: "rgba(0,0,0,.35)" }}>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6, alignItems: "center", marginBottom: 8 }}>
              <span style={{ fontFamily: SERIF, color: GOLD_HI, fontSize: 14 }}>Upgrade path: {cur.slot}</span>
              {multi.map((s: GSlot) => (
                <button key={s.slot} type="button" className="wf-tab" onClick={() => setSel(s.slot)} style={{ fontSize: 11, padding: "2px 8px", borderRadius: 999, border: `1px solid ${s.slot === cur.slot ? GOLD_HI : "#4a3d22"}`, background: s.slot === cur.slot ? "rgba(245,215,122,.15)" : "transparent", color: s.slot === cur.slot ? "#fff" : MUTED }}>{s.slot}</button>
              ))}
            </div>
            <div style={{ display: "grid", gap: 4 }}>
              {cur.picks.map((p: GPick, k: number) => {
                const info = ITEM_INFO[p.item];
                const q = info ? QUALITY[info[1]] : [GOLD, ""];
                const r = gearPick(cur, lv);
                const isNow = r.i === k && r.state === "now";
                const got = !!ck[p.id];
                return (
                  <div key={`${p.id}-${k}`} style={{ display: "flex", gap: 8, alignItems: "center", padding: "4px 6px", borderRadius: 6, border: `1px solid ${isNow && !got ? ORANGE : "transparent"}`, background: isNow ? "rgba(255,128,0,.08)" : "transparent" }}>
                    <TickBox on={got} onClick={() => toggle(p.id)} small color={q[0]} />
                    <Icon icon={info ? info[0] : ""} size={28} ring={q[0]} name={p.name} tip={`${q[1]} · ${p.src}`} />
                    <div style={{ minWidth: 0, flex: 1, fontSize: 12 }}>
                      <span style={{ color: q[0], fontWeight: 600 }}>{p.name}</span>{p.alt ? <span style={{ color: MUTED }}> or <span style={{ color: ITEM_INFO[p.alt] ? QUALITY[ITEM_INFO[p.alt][1]][0] : INK, fontWeight: 600 }}>{p.alt}</span></span> : null}
                      {isNow && !got ? <span style={{ marginLeft: 6, fontSize: 9, fontWeight: 700, padding: "0 5px", borderRadius: 3, background: ORANGE, color: "#1a0d00" }}>CHASE</span> : null}
                      <div style={{ fontSize: 10, color: MUTED }}>Lv {p.lv} · {p.src}</div>
                      {prePick(p) ? <div style={{ marginTop: 2 }}><span className="wf-mark wf-mark-notes" style={{ fontSize: 9 }}>{NOTES_PRE}</span></div> : null}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ) : null}
        <div style={{ fontSize: 10, color: MUTED, marginTop: 8 }}>Items, levels and sources: your gear notes (unchanged). Item icon and quality colour: Wowhead's WoW Forever item database, read Oct 30. Empty slots are ones your notes don't fill.</div>
        <PreLine lead="Gear past 30: your notes' picks are tagged “from notes, pre-launch, stats unconfirmed” (no stats shown). Past-30 slots your notes don't fill:" />
      </Frame>
    </div>
  );
}

const DUNGEONS: string[][] = WF_DATA.dungeons.DUNGEONS;
const DUN_NOTES_LOOT = WF_DATA.dungeons.DUN_NOTES_LOOT;
function dunCell(t: string): ReactNode {
  if (DUN_NOTES_LOOT.indexOf(t) >= 0) return <span style={{ display: "inline-flex", flexDirection: "column", gap: 2 }}>{t}<span className="wf-mark wf-mark-notes" style={{ fontSize: 9, alignSelf: "flex-start" }}>{NOTES_PRE}</span></span>;
  const k = t.indexOf(PRE_LABEL); return k < 0 ? t : <span>{t.slice(0, k)}<span className="wf-pre wf-pre-sm">{PRE_LABEL}</span>{t.slice(k + PRE_LABEL.length)}</span>;
}
function dunTop(lv: string): number { const m = lv.match(/(\d+)\D*$/); return m ? Number(m[1]) : 0; }
// Stable check ids: the first 12 rows keep their old index so saved ticks survive; added rows get names.
const DKEYS: string[] = WF_DATA.dungeons.DKEYS;

// ===== Vorgash totem presets per dungeon: from "Totem presets per dungeon" in Shaman - Gear and Dungeons.md (notes commit f0d0af1) =====
type PSlot = { t: string; icon: string; inh?: boolean; tag?: string } | null;
type PUse = { preset: string; icon: string; when?: string; earth: PSlot; fire: PSlot; water: PSlot; air: PSlot; gate?: string };
type PSub = { name: string; lv: string; press: string | null; uses: PUse[]; change?: string; click?: string; flag?: string };
const T_SOE = { t: "Strength of Earth", icon: "spell_nature_earthbindtotem" };
const T_TREMOR = { t: "Tremor", icon: "spell_nature_tremortotem" };
const T_SEAR = { t: "Searing", icon: "spell_fire_searingtotem" };
const T_HS = { t: "Healing Stream", icon: "inv_spear_04" };
const T_GROUND = { t: "Grounding", icon: "spell_nature_groundingtotem" };
const T_DIS = { t: "Disease Cleansing", icon: "spell_nature_diseasecleansingtotem" };
const PRESET_BASE: Record<string, { icon: string; key: string; from: number; earth: PSlot; fire: PSlot; water: PSlot; air: PSlot }> = WF_DATA.dungeons.PRESET_BASE;
// A preset as the notes build it, with the row's changes laid over it. Slots the row doesn't change are tagged "preset default".
function pu(preset: string, when?: string, ch: { earth?: PSlot; fire?: PSlot; water?: PSlot; air?: PSlot } = {}, gate?: string): PUse {
  const b = PRESET_BASE[preset];
  const s = (k: "earth" | "fire" | "water" | "air"): PSlot => (ch[k] !== undefined ? ch[k] ?? null : b[k] ? { ...(b[k] as { t: string; icon: string }), inh: true } : null);
  return { preset, icon: b.icon, when, earth: s("earth"), fire: s("fire"), water: s("water"), air: s("air"), gate };
}
const P_NONE_W = { t: "none: no Water totem until the level-20 quest", icon: "", inh: true, tag: "none" };
const P_NONE_A = { t: "none: the macro drops Strength of Earth and Searing only", icon: "", inh: true, tag: "none" };
const P_MACRO: PUse = { preset: "Totem macro", icon: "", when: "no presets before 20", earth: { ...T_SOE, inh: true, tag: "macro" }, fire: { ...T_SEAR, inh: true, tag: "macro" }, water: P_NONE_W, air: P_NONE_A };
const P_E = "Call of the Elements", P_S = "Call of the Spirits", P_A = "Call of the Ancestors";
const PRESETS: PSub[][] = WF_DATA.dungeons.PRESETS;
const P_ELEM: [string, string, string][] = [["earth", "Earth", "#b3874a"], ["fire", "Fire", "#ff6a2a"], ["water", "Water", "#3fa9ff"], ["air", "Air", "#c8d8e8"]];
const P_SHORT: Record<string, string> = { "Call of the Elements": "Elements", "Call of the Spirits": "Spirits", "Call of the Ancestors": "Ancestors", "Totem macro": "Macro" };

function PresetCell({ i, open, onToggle }: { i: number; open: boolean; onToggle: (i: number) => void }) {
  const subs = PRESETS[i];
  const uses = subs.length === 1 ? subs[0].uses : [];
  const label = subs.length > 1 ? `${subs.length} dungeons` : uses.length ? uses.map((u: PUse) => P_SHORT[u.preset] ?? u.preset).join(" → ") : "not in notes";
  return (
    <button type="button" className="wf-btn" aria-expanded={open} onClick={() => onToggle(i)} style={{ display: "inline-flex", alignItems: "center", gap: 4, padding: "2px 8px 2px 2px", borderRadius: 6, border: `1px solid ${open ? GOLD_HI : "#4a3d22"}`, background: open ? "rgba(245,215,122,.12)" : "#14110d", color: label === "not in notes" ? MUTED : INK, fontSize: 12, whiteSpace: "nowrap" }}>
      {uses.length ? uses.map((u: PUse, k: number) => (u.icon ? <Icon key={k} icon={u.icon} size={20} name={u.preset} tip={u.when} /> : <span key={k} style={{ width: 20, height: 20, borderRadius: 4, border: "1px dashed #6b5a33", flex: "none", fontSize: 9, color: MUTED, display: "flex", alignItems: "center", justifyContent: "center" }}>/m</span>)) : <span style={{ width: 20, height: 20, borderRadius: 4, border: "1px dashed #6b5a33", flex: "none" }} />}
      <span style={{ marginLeft: 2 }}>{label}</span><span style={{ color: GOLD_HI, fontSize: 10 }}>{open ? "▾" : "▸"}</span>
    </button>
  );
}

function PresetPanel({ open, setOpen }: { open: number[]; setOpen: (o: number[]) => void }) {
  const all = open.length === PRESETS.length;
  const slot = (s: PSlot, label: string, color: string) => (
    <div key={label} style={{ display: "flex", alignItems: "center", gap: 6, minWidth: 0, padding: 6, borderRadius: 6, border: s ? (s.inh ? `1px dashed ${color}66` : `1px solid ${GOLD_HI}`) : "1px solid #3a3020", background: s ? (s.inh ? "rgba(0,0,0,.25)" : `linear-gradient(180deg, ${color}2a, #0b0a08)`) : "rgba(0,0,0,.25)", boxShadow: s && !s.inh ? "0 0 8px rgba(245,215,122,.35)" : "none" }}>
      {s && s.icon ? <Icon icon={s.icon} size={28} name={`${label}: ${s.t}`} ring={s.inh ? MUTED : color} dim={!!s.inh} /> : <span style={{ width: 28, height: 28, borderRadius: 4, border: "1px dashed #6b5a33", flex: "none" }} />}
      <div style={{ minWidth: 0 }}>
        <div style={{ fontSize: 10, letterSpacing: ".1em", textTransform: "uppercase", color }}>{label} {s ? <span style={{ letterSpacing: 0, textTransform: "none", padding: "0 4px", borderRadius: 3, fontSize: 9, color: s.inh ? MUTED : "#1a1206", background: s.inh ? "transparent" : GOLD_HI, border: s.inh ? "1px solid #4a3d22" : "none" }}>{s.tag ?? (s.inh ? "preset default" : "changed")}</span> : null}</div>
        <div style={{ fontSize: 12, color: s ? (s.inh ? MUTED : INK) : MUTED, fontStyle: s ? "normal" : "italic" }}>{s ? s.t : "not in notes"}</div>
      </div>
    </div>
  );
  const use = (u: PUse, k: number) => (
    <div key={k} style={{ marginTop: 6 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 4, fontSize: 12 }}>
        {u.icon ? <Icon icon={u.icon} size={20} name={u.preset} /> : null}
        <span style={{ color: "#5fb0ff" }}>{u.preset}</span>{u.when ? <span style={{ color: MUTED }}>· {u.when}</span> : null}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))", gap: 6 }}>
        {P_ELEM.map((e: [string, string, string]) => slot(u[e[0] as "earth" | "fire" | "water" | "air"], e[1], e[2]))}
      </div>
      {u.gate ? <div style={{ fontSize: 11, color: ORANGE, marginTop: 4 }}>⚠ {u.gate}</div> : null}
    </div>
  );
  const card = (p: PSub) => (
    <div key={p.name} className="wf-pop" style={{ padding: 10, borderRadius: 10, border: `1px solid ${SHAMAN}88`, borderLeft: `4px solid ${SHAMAN}`, background: "linear-gradient(180deg,#17130e,#0b0a08)" }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap" }}>
        <span style={{ fontFamily: SERIF, color: GOLD_HI, fontSize: 15 }}>{p.name}</span>
        {p.lv ? <span style={{ fontSize: 11, color: MUTED }}>{p.lv}</span> : null}
        {dunTop(p.lv) > 30 ? <span className="wf-pre wf-pre-sm">31+ pre-launch</span> : null}
      </div>
      <div style={{ fontSize: 11, color: MUTED, margin: "2px 0 2px" }}>Press: {p.press ? `“${p.press}”` : <i>not in notes</i>}</div>
      {p.uses.map(use)}
      {p.change ? <div style={{ fontSize: 12, color: INK, marginTop: 6 }}>Changes: “{p.change}”</div> : null}
      {p.click ? <div style={{ fontSize: 12, color: INK, marginTop: 2 }}>Click when needed: {p.click}</div> : null}
      {p.flag ? <div style={{ fontSize: 11, color: ORANGE, marginTop: 4 }}>⚠ {p.flag}</div> : null}
    </div>
  );
  return (
    <div style={{ borderRadius: 12, border: `1px solid ${GOLD}`, background: "#0f0d0b", padding: 12 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <Icon icon="classicon_shaman" size={28} ring={SHAMAN} />
        <span style={{ fontFamily: SERIF, color: GOLD_HI, fontSize: 16 }}>Vorgash's totem presets</span>
        <span style={{ fontSize: 12, color: MUTED }}>Click a Preset cell in the table, or</span>
        <button type="button" className="wf-btn" onClick={() => setOpen(all ? [] : PRESETS.map((_p: PSub[], i: number) => i))} style={{ padding: "3px 12px", borderRadius: 6, border: `1px solid ${GOLD}`, background: all ? "transparent" : "linear-gradient(180deg,#7a1a12,#3d0c08)", color: GOLD_HI, fontSize: 12, fontWeight: 700 }}>{all ? "Hide all" : "Show all"}</button>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 6, marginTop: 10 }}>
        {Object.keys(PRESET_BASE).map((k: string) => { const b = PRESET_BASE[k]; return (
          <div key={k} style={{ display: "flex", alignItems: "center", gap: 8, padding: 6, borderRadius: 8, border: "1px solid #3a3020", background: "rgba(0,0,0,.3)" }}>
            <Icon icon={b.icon} size={30} name={k} tip={`${b.key} · from ${b.from}`} ring="#5fb0ff" />
            <div style={{ fontSize: 11, color: MUTED, lineHeight: 1.35 }}><span style={{ color: "#5fb0ff", fontSize: 12 }}>{k}</span> ({b.key}) · from {b.from}<br />{P_ELEM.map((e: [string, string, string]) => { const s = b[e[0] as "earth" | "fire" | "water" | "air"]; return `${e[1]} ${s ? s.t : "per dungeon"}`; }).join(" · ")}</div>
          </div>
        ); })}
      </div>
      {open.length ? (
        <div style={{ display: "grid", gap: 10, marginTop: 10 }}>
          {open.slice().sort((a: number, b: number) => a - b).map((i: number) => (
            <div key={i}>
              {PRESETS[i].length > 1 ? <div style={{ fontSize: 11, color: GOLD, letterSpacing: ".1em", textTransform: "uppercase", marginBottom: 4 }}>{DUNGEONS[i][0]}</div> : null}
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: 8 }}>{PRESETS[i].map(card)}</div>
            </div>
          ))}
        </div>
      ) : null}
      <div style={{ fontSize: 11, color: MUTED, marginTop: 10, lineHeight: 1.5 }}>
        <div>Source: Shaman - Gear and Dungeons.md › “Totem presets per dungeon” (notes commit f0d0af1, untested in game). Gold tiles are what the row changes; dashed tiles are that preset's normal totem from the three-presets table.</div>
        <div>“Before 20 there are no presets: the pre-20 totem macro drops Strength of Earth and Searing only (no Water totem until the level-20 quest). On the 6-plate, Shift+6 is Lesser Healing Wave; Ancestors arrives at 40, after the 12-plate swap, so it only ever lives on the 12-plate's Shift+6.”</div>
        <div>Shaman - Enhancement.md agrees: “Call of the Ancestors (40) is a third: the dungeon set, rebuilt at each dungeon's entrance for whatever lasts the whole run.”</div>
        <div>“<b style={{ color: INK }}>Ancestors is the dungeon set:</b> rebuild it at the dungeon entrance for whatever that dungeon needs, then it is one press all run.” “<b style={{ color: INK }}>The rule:</b> a problem that lasts the whole run goes in the preset. A problem that shows up on one boss or one pack gets clicked from the Bottom Right bar (Poison Cleansing, Tremor before 30, Earthbind).”</div>
        <div>Slots follow the Classic elements; the note says: “Confirm on the Totem Bar on day one; Forever could have moved one.”</div>
      </div>
    </div>
  );
}

const INSTALLED: string[][] = WF_DATA.addons.INSTALLED;

const TRAINER_RAW: Record<string, Record<number, string>> = WF_DATA.trainers.TRAINER_RAW;
// ===== v3: level-driven page, tracking, Next ding, launch night =====
const TRAIN_SRC: Record<string, { label: string; url: string }> = WF_DATA.trainers.TRAIN_SRC;
const TRAIN_NOTE = WF_DATA.trainers.TRAIN_NOTE;
function trainerAt(cls: string, lv: number): string[] {
  const raw = TRAINER_RAW[cls][lv];
  return raw ? raw.split("|") : [];
}
function nextTrainerLevel(cls: string, lv: number): number | null {
  const ks = Object.keys(TRAINER_RAW[cls]).map((k: string) => parseInt(k, 10)).sort((a: number, b: number) => a - b);
  const k = ks.find((x: number) => x > lv);
  return k === undefined ? null : k;
}

const SKILL_KEYS: string[] = WF_DATA.characters.SKILL_KEYS;
const CHAR_PROFS: Record<string, string[]> = WF_DATA.characters.CHAR_PROFS;

type Tick = { id: string; text: string; meta?: string; def?: boolean };
const LAUNCH_ITEMS: { group: string; icon: string; items: Tick[] }[] = WF_DATA.launch_night.LAUNCH_ITEMS;
type Route = { id: string; who: string; zone: string; color: string; icon: string; steps: string[]; flag: string; src: { label: string; url: string }[] };
const ROUTES: Route[] = WF_DATA.launch_night.ROUTES;
const PROGRESS: { heading: string; items: Tick[] }[] = WF_DATA.progress.PROGRESS;
// Order is part of the export code: only ever append.
// Progress groups render with Corvin's milestones first (MAIN / ALT); PROGRESS and CHECK_IDS order are unchanged.
function progRank(g: { heading: string }): number { const i = PROGRESS.findIndex((x: { heading: string }) => x.heading === g.heading); const v = PROGRESS.findIndex((x: { heading: string }) => x.heading === "Vorgash milestones"); return g.heading === "Corvin milestones" && v >= 0 ? v - 0.5 : i; }
const CHECK_IDS: string[] = [
  ...LAUNCH_ITEMS.flatMap((g: { items: Tick[] }) => g.items.map((t: Tick) => t.id)),
  ...ROUTES.flatMap((r: Route) => r.steps.map((_s: string, i: number) => `${r.id}${i}`)),
  ...SHAM_GEAR.map((_r: string[], i: number) => `gs${i}`),
  ...LOCK_GEAR.map((_r: string[], i: number) => `gl${i}`),
  ...DKEYS.map((k: string) => `dv${k}`),
  ...DKEYS.map((k: string) => `dc${k}`),
  ...PROGRESS.flatMap((g: { items: Tick[] }) => g.items.map((t: Tick) => t.id)),
  ...GEAR_EXTRA_IDS,
];
const DEFAULT_CHECKS: Record<string, boolean> = {};
PROGRESS.forEach((g: { items: Tick[] }) => g.items.forEach((t: Tick) => { if (t.def) DEFAULT_CHECKS[t.id] = true; }));

type Saved = { lvV: number; lvC: number; sk: Record<string, number>; ck: Record<string, boolean> };
const STORE_KEY = "wf-command-table";
// If you send me an export code in chat, I paste it here so it becomes the page's starting state.
const BAKED_CODE = "";
declare const WF_DATA: any;
declare const WF_STORE: { initial: any; online: boolean; save: (part: string, value: unknown) => void; onStatus: (fn: (ok: boolean) => void) => () => void };
const clampN = (n: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, Math.round(n)));
// Grok's WF1 codes are a bitfield over the Nov 3 tick layout. That layout is frozen here, so old codes
// keep importing however the feed grows. New exports are WF2: the ticked ids by name, base64url JSON.
const WF1_IDS: string[] = ["la0","la1","la2","la3","la4","la5","la6","la7","rv0","rv1","rv2","rv3","rv4","rv5","rv6","rc0","rc1","rc2","rc3","rc4","rc5","rc6","rc7","gs0","gs1","gs2","gs3","gs4","gs5","gs6","gs7","gs8","gs9","gs10","gs11","gs12","gs13","gs14","gs15","gs16","gs17","gl0","gl1","gl2","gl3","gl4","gl5","gl6","gl7","gl8","gl9","gl10","gl11","gl12","gl13","gl14","gl15","gl16","gl17","gl18","gl19","gl20","gl21","dv0","dv1","dv2","dv3","dv4","dv5","dv6","dvgnomer","dv7","dv8","dv9","dv10","dvblackmaw","dv11","dvshaper","dc0","dc1","dc2","dc3","dc4","dc5","dc6","dcgnomer","dc7","dc8","dc9","dc10","dcblackmaw","dc11","dcshaper","p0","p1","p2","p3","p4","p5","p6","p7","p8","p9","p10","p11","p12","p13","p14","p15","p16","p17","p18","p19","p20","p21","p22","p23","p24","p25","gs15b","gl8b","gl9b","gl14b","gl17b","gl18b"];
const b64u = (t: string) => btoa(unescape(encodeURIComponent(t))).replace(/=+$/, "").replace(/\+/g, "-").replace(/\//g, "_");
const unb64u = (t: string) => decodeURIComponent(escape(atob(t.replace(/-/g, "+").replace(/_/g, "/"))));
function encodeState(s: Saved): string {
  const k = Object.keys(s.ck).filter((id: string) => s.ck[id]).sort();
  return "WF2-" + b64u(JSON.stringify({ v: s.lvV, c: s.lvC, s: SKILL_KEYS.map((key: string) => s.sk[key] ?? 0), k }));
}
function decodeState(code: string): Saved | null {
  const t = code.trim();
  if (t.indexOf("WF2-") === 0) {
    try {
      const o = JSON.parse(unb64u(t.slice(4)));
      if (typeof o.v !== "number" || typeof o.c !== "number" || !Array.isArray(o.s) || !Array.isArray(o.k)) return null;
      const sk: Record<string, number> = {};
      SKILL_KEYS.forEach((key: string, i: number) => { sk[key] = clampN(Number(o.s[i]) || 0, 0, 300); });
      const ck: Record<string, boolean> = {};
      o.k.forEach((id: unknown) => { if (typeof id === "string") ck[id] = true; });
      return { lvV: clampN(o.v, 1, 60), lvC: clampN(o.c, 1, 60), sk, ck };
    } catch (e: unknown) { return null; }
  }
  const parts = t.split("-");
  if (parts.length !== 5 || parts[0] !== "WF1") return null;
  const lvV = parseInt(parts[1], 10);
  const lvC = parseInt(parts[2], 10);
  const sks = parts[3].split(".").map((x: string) => parseInt(x, 10));
  if (isNaN(lvV) || isNaN(lvC) || sks.length !== SKILL_KEYS.length || sks.some((x: number) => isNaN(x))) return null;
  if (!/^[0-9a-f]+$/i.test(parts[4])) return null;
  const sk: Record<string, number> = {};
  SKILL_KEYS.forEach((k: string, i: number) => { sk[k] = clampN(sks[i], 0, 300); });
  const ck: Record<string, boolean> = {};
  const hex = parts[4].toLowerCase();
  for (let i = 0; i < hex.length; i++) {
    const n = parseInt(hex[i], 16);
    for (let j = 0; j < 4; j++) { const id = WF1_IDS[i * 4 + j]; if (id && (n >> (3 - j)) & 1) ck[id] = true; }
  }
  return { lvV: clampN(lvV, 1, 60), lvC: clampN(lvC, 1, 60), sk, ck };
}
function probeStorage(): boolean {
  try {
    const ls = window.localStorage;
    ls.setItem("wf-probe", "1");
    const ok = ls.getItem("wf-probe") === "1";
    ls.removeItem("wf-probe");
    return ok;
  } catch (e: unknown) {
    return false;
  }
}
function initialState(): Saved {
  const baked = BAKED_CODE ? decodeState(BAKED_CODE) : null;
  if (baked) return baked;
  const sk: Record<string, number> = {};
  SKILL_KEYS.forEach((k: string) => { sk[k] = 0; });
  return { lvV: 1, lvC: 1, sk, ck: { ...DEFAULT_CHECKS } };
}

