function profStep(p: ProfDef, skill: number): PStepRaw | undefined {
  const s = Math.max(1, skill);
  if (!p.steps.length) return undefined;
  const idx = p.steps.findIndex((st: PStepRaw) => s >= st[0] && s < st[1]);
  return p.steps[idx >= 0 ? idx : p.steps.length - 1];
}
function trainReqLevel(t: [number, string]): number | null {
  const m = /level (\d+)/.exec(t[1]);
  return m ? parseInt(m[1], 10) : null;
}

function nextTalent(cls: string, level: number): { lv: number; name: string; rank: number; tal?: Tal; why: string } | null {
  const seq = SEQ[cls === "shaman" ? "enh_lvl" : "aff_lvl"];
  const lv = Math.max(10, level + 1);
  const idx = lv - 10;
  if (lv > 60 || idx >= seq.length) return null;
  const name = seq[idx];
  const rank = seq.slice(0, idx + 1).filter((n: string) => n === name).length;
  const tal = TAL_INDEX[cls][name];
  const why = WHY[name] ?? (tal ? `Talent text: ${rank > 1 ? tal.rm : tal.r1}` : "");
  return { lv, name, rank, tal, why };
}

