function SmallTag({ label, tone }: { label: string; tone: "ok" | "warn" | "note" }) {
  const c = tone === "ok" ? FEL : tone === "warn" ? ORANGE : GOLD_HI;
  return <span style={{ display: "inline-block", fontSize: 10, fontWeight: 700, letterSpacing: ".06em", padding: "1px 6px", borderRadius: 999, border: `1px solid ${c}88`, color: c, background: "rgba(0,0,0,.45)", whiteSpace: "nowrap" }}>{label}</span>;
}

function CorvinFirstSession({ level }: { level: number }) {
  const [done, setDone] = useState<Record<string, boolean>>(() => ({ ...(WF_STORE.initial?.first || {}) }));
  useEffect(() => { WF_STORE.save("first", done); }, [done]);
  const [hub, setHub] = useState<string>("all");
  const [hideDone, setHideDone] = useState<boolean>(false);
  const [now, setNow] = useState<number>(Date.now());
  useEffect(() => { const id = setInterval(() => setNow(Date.now()), 30000); return () => clearInterval(id); }, []);
  const all = FIRST_ROUTE.reduce((n: number, g: FirstHub) => n + g.steps.length, 0);
  const got = Object.keys(done).filter((k: string) => done[k]).length;
  const firstOpen = FIRST_ROUTE.map((g: FirstHub) => g.steps).reduce((a: FirstStep[], b: FirstStep[]) => a.concat(b), []).find((s: FirstStep) => !done[s.id]);
  const left = Math.max(0, LAUNCH_MS - now);
  const lh = Math.floor(left / 3600000);
  const lm = Math.floor((left % 3600000) / 60000);
  const nextStop = FIRST_TRAINER.find((t: [number, string]) => t[0] > level);
  const tals = [10, 11, 12].map((lv: number) => {
    const seq = SEQ.aff_lvl;
    const name = seq[lv - 10];
    const rank = seq.slice(0, lv - 9).filter((n: string) => n === name).length;
    return { lv, name, rank, tal: TAL_INDEX.warlock[name] };
  });
  const corv = PROFS.filter((p: ProfDef) => CHAR_PROFS.C.indexOf(p.key) >= 0);
  const profExtra: Record<string, string> = {
    tail: "Hold your Linen. Journeyman at 50 needs character level 10.",
    ench: "Your notes: Lesser Magic Wand at character level 5, skill 10, from the Enchanting trainer, the biggest upgrade before 10. Brill trainer per ForeverDB: Vance Undergloom (Classic data, may have moved).",
    fa: "Healing Potions live in First Aid now (your notes). Brill trainer per ForeverDB: Nurse Neela (Classic data, may have moved).",
    cook: "Camping 101: Cooking from Eleanor Shackleton in Brill at 5 (Bind on Forever).",
  };
  const card = (title: string, icon: string, children: ReactNode, accent?: string) => (
    <div style={{ padding: 10, borderRadius: 8, border: `1px solid ${accent ?? "#3a3020"}`, background: "rgba(0,0,0,.32)" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: GOLD, textTransform: "uppercase", letterSpacing: ".12em", marginBottom: 6 }}><Icon icon={icon} size={20} />{title}</div>
      {children}
    </div>
  );
  const pill = (on: boolean, label: string, onClick: () => void) => (
    <button key={label} type="button" className="wf-btn" onClick={onClick} style={{ padding: "3px 10px", borderRadius: 999, border: `1px solid ${on ? GOLD_HI : "#4a3d22"}`, background: on ? "linear-gradient(180deg,#7a1a12,#3d0c08)" : "#0b0a08", color: on ? GOLD_HI : INK, fontSize: 12, fontWeight: on ? 700 : 400 }}>{label}</button>
  );
  return (
    <div style={{ borderRadius: 12, border: `1px solid ${GOLD}`, background: `radial-gradient(ellipse 60% 50% at 15% 0%, ${WARLOCK}2e, transparent 70%), linear-gradient(180deg, #1d1710, #0a0907)`, boxShadow: "0 6px 24px rgba(0,0,0,.5)", overflow: "hidden", color: INK }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "10px 14px", flexWrap: "wrap", background: "linear-gradient(90deg, rgba(60,40,120,.55), rgba(0,0,0,0))", borderBottom: "1px solid #3a3020" }}>
        <Icon icon="classicon_warlock" size={36} ring={WARLOCK} />
        <div style={{ flex: "1 1 220px" }}>
          <div style={{ fontFamily: SERIF, fontSize: 19, color: GOLD_HI, textShadow: "0 1px 0 #000" }}>Launch Night: Corvin's first session <RoleBadge who="C" /></div>
          <div style={{ fontSize: 12, color: MUTED }}>Undead Warlock · Deathknell → Brill → Tirisfal, levels 1 to about 12 · {got}/{all} quest-log steps</div>
        </div>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontFamily: SERIF, fontSize: 15, color: "#fff" }}>Wed Nov 4 · 6:00 PM ET</div>
          <div className={left > 0 && left < 86400000 ? "wf-pulse" : undefined} style={{ fontSize: 11, color: left > 0 ? GOLD_HI : FEL, fontVariantNumeric: "tabular-nums" }}>{left > 0 ? `servers in ${lh}h ${pad(lm)}m` : "Servers are up"}</div>
        </div>
      </div>
      <div style={{ height: 4, background: "#0b0a08" }}><div style={{ height: 4, width: `${all ? Math.round((got / all) * 100) : 0}%`, background: `linear-gradient(90deg, ${WARLOCK}, ${FEL})`, transition: "width .3s ease" }} /></div>

      <div style={{ padding: 14, display: "grid", gap: 12 }}>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8, alignItems: "center", fontSize: 12 }}>
          <SmallTag label="Official" tone="ok" /><span>Servers open Wed Nov 4, 6:00 PM ET (Blizzard launch post, Oct 29).</span>
          <SmallTag label="Secondhand" tone="warn" /><span>Maintenance 1:00–6:00 PM ET, per a Blizzard Support listing quoted by forevermastery.com (read Nov 2). Not seen on Blizzard's own pages.</span>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(330px, 1fr))", gap: 12, alignItems: "start" }}>
          <div style={{ padding: 10, borderRadius: 8, border: `1px solid ${WARLOCK}88`, borderLeft: `4px solid ${WARLOCK}`, background: "rgba(0,0,0,.35)" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
              <span style={{ fontFamily: SERIF, color: GOLD_HI, fontSize: 15, marginRight: 4 }}>Quest log</span>
              {pill(hub === "all", "All", () => setHub("all"))}
              {FIRST_ROUTE.map((g: FirstHub) => pill(hub === g.hub, `${g.hub} ${g.lv}`, () => setHub(g.hub)))}
              {pill(hideDone, hideDone ? "Show done" : "Hide done", () => setHideDone(!hideDone))}
              {got ? pill(false, "Clear", () => setDone({})) : null}
            </div>
            {FIRST_ROUTE.filter((g: FirstHub) => hub === "all" || g.hub === hub).map((g: FirstHub) => {
              const shown = g.steps.filter((s: FirstStep) => !(hideDone && done[s.id]));
              const gd = g.steps.filter((s: FirstStep) => done[s.id]).length;
              return (
                <div key={g.hub} style={{ marginBottom: 8 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, color: GOLD, textTransform: "uppercase", letterSpacing: ".12em", margin: "6px 0 2px", borderBottom: "1px solid #3a3020", paddingBottom: 3 }}>
                    <Icon icon={g.icon} size={18} />{g.hub} · {g.lv}<span style={{ marginLeft: "auto", color: gd === g.steps.length ? FEL : MUTED, letterSpacing: 0 }}>{gd}/{g.steps.length}</span>
                  </div>
                  {shown.length ? shown.map((s: FirstStep) => (
                    <div key={s.id} style={{ display: "flex", alignItems: "flex-start", gap: 6 }}>
                      <span className={firstOpen && firstOpen.id === s.id ? "wf-next" : undefined} style={{ marginTop: 5, borderRadius: 4, flex: "none" }}><Icon icon={s.icon} size={22} dim={!!done[s.id]} /></span>
                      <TickBox on={!!done[s.id]} onClick={() => setDone({ ...done, [s.id]: !done[s.id] })} color={WARLOCK} meta={s.tip}
                        text={<span><span style={{ color: GOLD_HI, fontWeight: 700 }}>[{s.lv}]</span> {s.text}{s.mine ? <span style={{ color: WARLOCK }}> (your notes)</span> : null}</span>} />
                    </div>
                  )) : <div style={{ fontSize: 12, color: FEL, padding: "4px 6px" }}>All done here.</div>}
                </div>
              );
            })}
            <div style={{ fontSize: 10, color: MUTED, marginTop: 4 }}>Order: Bind on Forever's Undead route (played on the beta, build 70291) cross-checked with ForeverDB's Deathknell guide; ForeverDB marks several Brill quest givers as Classic data not yet seen in Forever. Your Launch Kit note (with your Undead route) isn't in the synced notes folder, so it isn't used here. Ticks are for tonight only and aren't saved.</div>
          </div>

          <div style={{ display: "grid", gap: 12 }}>
            {card("Trainer stops", "inv_misc_book_09", (
              <div style={{ display: "grid", gap: 6 }}>
                {FIRST_TRAINER.map((t: [number, string]) => {
                  const spells = trainerAt("warlock", t[0]);
                  const isNext = !!nextStop && nextStop[0] === t[0];
                  const past = t[0] <= level;
                  return (
                    <div key={t[0]} className={isNext ? "wf-next" : undefined} style={{ display: "flex", gap: 8, alignItems: "flex-start", padding: 6, borderRadius: 6, border: `1px solid ${isNext ? GOLD_HI : "#2c2416"}`, background: "rgba(0,0,0,.3)", opacity: past && !isNext ? 0.65 : 1 }}>
                      <span style={{ fontFamily: SERIF, color: GOLD_HI, fontSize: 16, minWidth: 26, textAlign: "center" }}>{t[0]}</span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                          {spells.map((sp: string) => {
                            const base = sp.replace(/ R\d+$/, "");
                            const ic = FIRST_SPELL_ICON[base];
                            return (
                              <span key={sp} style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 12, padding: "1px 7px 1px 2px", borderRadius: 999, border: "1px solid #6b5a33", background: "#0b0a08", color: "#fff" }}>
                                {ic ? <Icon icon={ic} size={18} /> : <span style={{ width: 4 }} />}{sp}
                              </span>
                            );
                          })}
                        </div>
                        <div style={{ fontSize: 10, color: MUTED, marginTop: 2 }}>{t[1]}{isNext ? " · your next stop" : ""}</div>
                      </div>
                    </div>
                  );
                })}
                <div style={{ fontSize: 10, color: MUTED }}>Spells: <a href={TRAIN_SRC.warlock.url} target="_blank" rel="noreferrer" style={{ color: GOLD_HI }}>{TRAIN_SRC.warlock.label}</a>, read Oct 30. Trainers and spots: Bind on Forever and ForeverDB (Maximillion and Rupert Boch are Classic data there). Corvin is level {level} on this page.</div>
              </div>
            ), WARLOCK)}

            {card("First talent points", "spell_holy_borrowedtime", (
              <div style={{ display: "grid", gap: 6 }}>
                {tals.map((t: { lv: number; name: string; rank: number; tal?: Tal }) => (
                  <div key={t.lv} style={{ display: "flex", gap: 8, alignItems: "center", fontSize: 12 }}>
                    {t.tal ? <Icon icon={t.tal.icon} size={28} ring={WARLOCK} name={t.name} tip={t.tal.r1} /> : null}
                    <div><span style={{ color: MUTED }}>Level {t.lv}:</span> <span style={{ color: "#fff", fontFamily: SERIF }}>{t.name}</span> <span style={{ color: GOLD_HI }}>{t.rank}{t.tal ? `/${t.tal.max}` : ""}</span></div>
                  </div>
                ))}
                <div style={{ fontSize: 12 }}>{WHY[tals[0].name] ?? ""}</div>
                <div style={{ fontSize: 10, color: MUTED }}>Icy Veins (Abide) Affliction leveling order, Nov 3, as in Talent trees. Without Legacy Talented; with Talented 5/5 the first point comes at 5 (your Class Hub note).</div>
              </div>
            ))}

            {card("Changed since your notes", "spell_shadow_soulgem", (
              <div style={{ display: "grid", gap: 8, fontSize: 12 }}>
                <div style={{ display: "flex", gap: 8, alignItems: "flex-start" }}>
                  <Icon icon="spell_shadow_haunting" size={28} ring={FEL} />
                  <div><SmallTag label="Official · Nov 2" tone="ok" /> <b style={{ color: "#fff" }}>Drain Soul</b>: the chance of a shard from damage alone is cut a lot; a kill still gives one. Finish mobs with Drain Soul to restock shards. Your Warlock - Overview note still says the killing blow isn't needed.</div>
                </div>
                <div style={{ display: "flex", gap: 8, alignItems: "flex-start" }}>
                  <Icon icon="spell_shadow_summonvoidwalker" size={28} ring={FEL} />
                  <div><SmallTag label="Official · Nov 2" tone="ok" /> <b style={{ color: "#fff" }}>Pets</b>: demons now get 2 Health per point of your Stamina (was 7.5). Expect a squishier Imp and Voidwalker; keep Health Funnel (12) in mind.</div>
                </div>
                <div style={{ fontSize: 10, color: MUTED }}>Blizzard beta development notes, updated Nov 2, read Nov 3 (via wowf.io and Wowhead).</div>
              </div>
            ), "#2f5a22")}
          </div>
        </div>

        {card("Profession first steps", "trade_engraving", (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(230px, 1fr))", gap: 8 }}>
            {corv.map((p: ProfDef) => {
              const s0 = p.steps[0];
              const s1 = p.steps[1];
              return (
                <div key={p.key} style={{ display: "flex", gap: 8, alignItems: "flex-start", fontSize: 12, padding: 6, borderRadius: 6, border: "1px solid #2c2416", background: "rgba(0,0,0,.25)" }}>
                  <Icon icon={p.icon} size={28} />
                  <div style={{ minWidth: 0 }}>
                    <div style={{ color: "#fff", fontFamily: SERIF }}>{p.name}</div>
                    {s0 ? <div><span style={{ color: GOLD_HI }}>{s0[0]}–{s0[1]}</span> {s0[2]} <span style={{ color: MUTED }}>({s0[3]} · {s0[4]})</span></div> : null}
                    {s1 ? <div style={{ color: MUTED }}>then {s1[2]} to {s1[1]}</div> : null}
                    <div style={{ color: INK, marginTop: 2 }}>{profExtra[p.key] ?? ""}</div>
                  </div>
                </div>
              );
            })}
          </div>
        ))}
        <div style={{ fontSize: 10, color: MUTED }}>Profession steps: ForeverArtisan guides (beta-checked Oct 10), as in Professions. Pre-launch beta data; spots and quest givers can move at launch.</div>

        <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
          {FIRST_SRC.map((x: { label: string; url: string }) => <a key={x.url} href={x.url} target="_blank" rel="noreferrer" style={{ fontSize: 11, padding: "2px 8px", borderRadius: 999, border: "1px solid #4a3d22", color: GOLD_HI, textDecoration: "none" }}>{x.label}</a>)}
        </div>
      </div>
    </div>
  );
}

function SavePanel({ storeOk, code, onImport, onReset }: { storeOk: boolean | null; code: string; onImport: (c: string) => string; onReset: () => void }) {
  const [txt, setTxt] = useState<string>("");
  const [msg, setMsg] = useState<string>("");
  const [copied, setCopied] = useState<string>("");
  const doCopy = () => {
    const fail = () => setCopied("Select the code and copy it");
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(code).then(() => setCopied("Copied"), fail);
      else fail();
    } catch (e: unknown) { fail(); }
    setTimeout(() => setCopied(""), 2200);
  };
  const ta = { width: "100%", boxSizing: "border-box" as const, padding: 8, borderRadius: 6, background: "#07070a", color: "#e8d9a8", border: "1px solid #3a3020", fontFamily: "ui-monospace, Menlo, Consolas, monospace", fontSize: 12, resize: "vertical" as const };
  return (
    <div style={{ borderRadius: 10, border: `1px solid ${storeOk ? FEL : ORANGE}`, background: "linear-gradient(180deg,#17130e,#0b0a08)", padding: 12, color: INK }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 8 }}>
        <Icon icon="inv_misc_note_01" size={28} ring={storeOk ? FEL : ORANGE} />
        <span style={{ fontFamily: SERIF, color: GOLD_HI, fontSize: 16 }}>Export / Import progress</span>
        <span style={{ fontSize: 11, fontWeight: 800, padding: "2px 8px", borderRadius: 4, background: storeOk ? FEL : ORANGE, color: "#000" }}>{storeOk === null ? "Checking…" : storeOk ? "Saved on the EliteDesk" : "EliteDesk offline: saving in this browser"}</span>
      </div>
      <div style={{ fontSize: 12, color: MUTED, marginBottom: 8 }}>
        {storeOk ? "Levels, skills and ticks save on the EliteDesk, so every device on your network sees the same progress. The code below is a backup, and old WF1 codes from Grok's page import here." : "Can't reach the EliteDesk right now, so changes are kept in this browser and sent over when it's back. The code below still works as a backup."}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 10 }}>
        <div>
          <div style={{ fontSize: 11, color: GOLD, textTransform: "uppercase", letterSpacing: ".1em", marginBottom: 4 }}>Your code</div>
          <textarea readOnly rows={2} value={code} onFocus={(e: { target: { select: () => void } }) => e.target.select()} style={ta} />
          <button type="button" className="wf-btn" onClick={doCopy} style={{ marginTop: 6, padding: "4px 12px", borderRadius: 6, border: `1px solid ${GOLD}`, background: "linear-gradient(180deg,#7a1a12,#3d0c08)", color: GOLD_HI, fontSize: 12, fontWeight: 700 }}>{copied || "Copy"}</button>
        </div>
        <div>
          <div style={{ fontSize: 11, color: GOLD, textTransform: "uppercase", letterSpacing: ".1em", marginBottom: 4 }}>Paste a code</div>
          <textarea rows={2} value={txt} placeholder="WF1-… or WF2-…" onChange={(e: { target: { value: string } }) => setTxt(e.target.value)} style={ta} />
          <div style={{ display: "flex", gap: 6, alignItems: "center", marginTop: 6, flexWrap: "wrap" }}>
            <button type="button" className="wf-btn" onClick={() => { const r = onImport(txt); setMsg(r); if (!r) setTxt(""); }} style={{ padding: "4px 12px", borderRadius: 6, border: `1px solid ${GOLD}`, background: "#14110d", color: GOLD_HI, fontSize: 12, fontWeight: 700 }}>Import</button>
            <button type="button" className="wf-btn" onClick={() => { onReset(); setMsg(""); }} style={{ padding: "4px 10px", borderRadius: 6, border: "1px solid #4a3d22", background: "transparent", color: MUTED, fontSize: 12 }}>Reset all</button>
            <span style={{ fontSize: 12, color: msg ? "#ff6060" : FEL }}>{msg}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default function App() {
  const PL = WF_DATA.page_lists;
  const [buildKey, setBuildKey] = useState<string>("path");
  const [st, setSt] = useState<Saved>(initialState);
  const [storeOk, setStoreOk] = useState<boolean | null>(null);
  const [launchOpen, setLaunchOpen] = useState<boolean>(true);
  const lvV = st.lvV;
  const lvC = st.lvC;
  const setLvV = (n: number) => setSt((s: Saved) => ({ ...s, lvV: clampN(n, 1, 60) }));
  const setLvC = (n: number) => setSt((s: Saved) => ({ ...s, lvC: clampN(n, 1, 60) }));
  const setSkill = (k: string, n: number) => setSt((s: Saved) => ({ ...s, sk: { ...s.sk, [k]: clampN(n, 0, 300) } }));
  const toggle = (id: string) => setSt((s: Saved) => ({ ...s, ck: { ...s.ck, [id]: !s.ck[id] } }));
  const code = encodeState(st);
  // Self-hosted: progress lives on the EliteDesk (WF_STORE, set up in main.tsx). WF1 codes stay as import/export.
  useEffect(() => {
    const s = WF_STORE.initial?.st;
    if (s && typeof s.lvV === "number") setSt({ lvV: clampN(s.lvV, 1, 60), lvC: clampN(s.lvC, 1, 60), sk: { ...initialState().sk, ...(s.sk || {}) }, ck: { ...(s.ck || {}) } });
    setStoreOk(WF_STORE.online);
    return WF_STORE.onStatus((ok: boolean) => setStoreOk(ok));
  }, []);
  useEffect(() => {
    if (storeOk === null) return;
    WF_STORE.save("st", st);
  }, [st]);
  const importCode = (c: string): string => { const s = decodeState(c); if (!s) return "That isn't a valid WF1 or WF2 code."; setSt(s); return ""; };
  const resetAll = () => { const s = initialState(); setSt({ lvV: 1, lvC: 1, sk: s.sk, ck: { ...DEFAULT_CHECKS } }); };

  const tDef = BUILD_DEFS.find((b: BuildDef) => b.key === buildKey) ?? BUILD_DEFS[0];
  const charLevel = tDef.cls === "shaman" ? lvV : lvC;
  const setCharLevel = tDef.cls === "shaman" ? setLvV : setLvC;
  const charName = tDef.cls === "shaman" ? "Vorgash" : "Corvin";
  const [preview, setPreview] = useState<number | null>(null);
  useEffect(() => { setPreview(null); }, [lvV, lvC]);
  const level = preview ?? charLevel;
  const setLevel = (n: number) => setPreview(n === charLevel ? null : n);
  const [pathSpec, setPathSpec] = useState<number>(1);
  useEffect(() => { if (level < 40 && pathSpec === 2) setPathSpec(1); }, [level, pathSpec]);
  const [nagaSpec, setNagaSpec] = useState<string>("aff");
  const [stagePick, setStagePick] = useState<string | null>(null);
  const [gearChar, setGearChar] = useState<string>("lock");
  const [presetOpen, setPresetOpen] = useState<number[]>([]);
  const togglePreset = (i: number) => setPresetOpen((o: number[]) => o.indexOf(i) >= 0 ? o.filter((x: number) => x !== i) : [...o, i]);
  const ssLv = SEQ.enh_lvl.indexOf("Stormstrike") + 10;
  const brandLv = SEQ.demo_lvl.indexOf("Demonic Brand") + 10;
  const wrackIdx = SEQ.aff_lvl.indexOf("Wrack");
  const wrackLv = wrackIdx >= 0 ? wrackIdx + 10 : 99;
  const autoStage = nagaSpec === "enh" ? (lvV >= ssLv ? "ss" : "early") : nagaSpec === "aff" ? (lvC >= wrackLv ? "a3" : lvC >= 14 ? "a2" : "a1") : (lvC >= brandLv ? "d2" : "d1");
  useEffect(() => { setStagePick(null); }, [lvV, lvC, nagaSpec]);
  const stageId = stagePick ?? autoStage;
  const goPath = (lv: number, sp: number) => {
    setBuildKey("path"); setPreview(lv === lvC ? null : lv); setPathSpec(sp);
    try { const el = document.getElementById("builds"); if (el) el.scrollIntoView({ behavior: "smooth", block: "start" }); } catch (e: unknown) { /* ignore */ }
  };

  const spec = NAGA[nagaSpec];
  const stage = spec.stages.find((s: Stage) => s.id === stageId) ?? spec.stages[0];
  const nagaLv = nagaSpec === "enh" ? lvV : lvC;
  const nagaColor = nagaSpec === "enh" ? SHAMAN : WARLOCK;
  const [prev12V, setPrev12V] = useState<boolean>(false);
  const [prev12C, setPrev12C] = useState<boolean>(false);
  const n12raw = NAGA12[nagaSpec];
  const n12 = nagaSpec === "aff" && lvC < wrackLv ? { ...n12raw, buttons: n12raw.buttons.map((b: any) => b.spell === "Wrack" ? { ...b, spell: "Drain Life", icon: "spell_shadow_lifedrain02", note: `Wrack goes here at ${wrackLv < 99 ? wrackLv : 51}` } : b) } : n12raw;
  const nagaWho = nagaSpec === "enh" ? "Vorgash" : "Corvin";
  const prev12 = nagaSpec === "enh" ? prev12V : prev12C;
  const setPrev12 = nagaSpec === "enh" ? setPrev12V : setPrev12C;
  const reached12 = nagaLv >= n12.from;
  const use12 = reached12 || prev12;
  const specOptions = [{ value: "aff", label: "Affliction" }, { value: "demo", label: "Demonology" }, { value: "enh", label: "Enhancement" }];

  return (
    <Page
      title="WoW Forever Command Table"
      summary="Your WoW Forever dashboard for Vorgash (Orc Enhancement Shaman) and Corvin (Undead Warlock): launch countdown, meta, patch feed, Corvin’s Affliction leveling path (Demonology Spec 2 at 40), live talent trees with a level slider, rotations, Naga binds, profession windows with a skill slider, gear, macro book, addons and progress. WoW-inspired design, not affiliated with Blizzard."
      width="wide"
    >
      <Hero />
      <Section heading="Next ding" id="ding" caption="Set each character's level here (or on the character cards). Talents, rotations, Naga stage, macros and these cards all follow it.">
        <Grid columns={2} plain>
          <NextDing who="C" level={lvC} setLevel={setLvC} skills={st.sk} />
          <NextDing who="V" level={lvV} setLevel={setLvV} skills={st.sk} />
        </Grid>
      </Section>
      <Section heading="Launch Night: Corvin's first session" id="first" caption="Quest-log checklist for the Undead start, about levels 1 to 12. Ticks save on the EliteDesk.">
        <CorvinFirstSession level={lvC} />
      </Section>
      <Section heading="Launch night" id="launch">
        <LaunchNight checks={st.ck} toggle={toggle} open={launchOpen} setOpen={setLaunchOpen} />
      </Section>
      <TableOfContents items={[
        { label: "Next ding", id: "ding" }, { label: "Corvin's first session", id: "first" }, { label: "Launch night", id: "launch" },
        { label: "Characters", id: "chars" }, { label: "Meta board", id: "meta" }, { label: "Patch and datamine feed", id: "feed" },
        { label: "Leveling path", id: "path" }, { label: "Talent trees", id: "builds" }, { label: "Rotations", id: "rotations" }, { label: "Naga V2 Pro binds", id: "naga" }, { label: "Professions", id: "profs" },
        { label: "Gear and dungeons", id: "gear" }, { label: "Macros", id: "macros" }, { label: "Addons", id: "addons" }, { label: "Progress tracker", id: "progress" },
      ]} />

      <Section heading="Characters" id="chars" caption="Set levels with the gold badge (− / type / +) and skills with − / +. Progress lives on this page: see Export / Import in the Progress tracker.">
        <Grid columns={2} plain>
          <CharCard c={CHARS[1]} who="C" level={lvC} setLevel={setLvC} skills={st.sk} setSkill={setSkill} />
          <CharCard c={CHARS[0]} who="V" level={lvV} setLevel={setLvV} skills={st.sk} setSkill={setSkill} />
        </Grid>
      </Section>

      <Section heading="Meta board" id="meta" caption="Pre-launch only: level-30 beta data and simulations. No level-60 logs exist until Nov 4.">
        <MetaBoard />
        <Callout tone={PL.meta_raid_watch.tone} lead={PL.meta_raid_watch.lead}>{PL.meta_raid_watch.text}</Callout>
        <LinkCards links={PL.meta_links} />
      </Section>

      <Section heading="Patch and datamine feed" id="feed">
        <Section heading="Pinned: your racials">
          <Grid columns={2}>
            <Properties items={PL.feed_racials_left} />
            <Properties items={PL.feed_racials_right} />
          </Grid>
        </Section>
        <Rows rows={PL.feed_rows} />
        <Section heading="Notes out of date">
          <BulletList items={PL.feed_notes_out_of_date} />
        </Section>
        <PreLine lead="Molten Core loot and Tier 1 (build 70707): Earthshaker, Band of Sulfuras, Choker of the Fire Lord, Felheart Raiment, The Earthfury:" mark="datamined" />
        <LinkCards links={PL.feed_links} />
      </Section>

      <Section heading="Corvin’s leveling path" id="path" caption="Level Affliction all the way to 60 on Icy Veins' 40/11 order (Demonic Sacrifice 41, Wrack 51). Dual Spec at 40 adds Demonology as Spec 2 for dungeons and raids. Click a level to see it in the talent tree.">
        <PathTimeline go={goPath} />
      </Section>

      <Section heading="Talent trees" id="builds" caption="Current Forever talent data (build 1.60.1.70707) with values from Blizzard's Nov 2 notes where they changed. The slider follows the character's level (Shaman builds: Vorgash, Warlock builds: Corvin); moving it previews another level without changing the character. Corvin's path levels Spec 1 Affliction to 60; Spec 2 (Demonology, for groups) unlocks at 40.">
        {preview !== null ? (
          <div className="wf-pop" style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", padding: "8px 12px", borderRadius: 8, border: `1px solid ${ORANGE}`, background: "rgba(255,128,0,.08)", color: INK, fontSize: 13 }}>
            <span>Previewing level <b style={{ color: GOLD_HI }}>{preview}</b>. {charName} is level {charLevel}.</span>
            <button type="button" className="wf-btn" onClick={() => setPreview(null)} style={{ padding: "3px 10px", borderRadius: 6, border: `1px solid ${GOLD}`, background: "#14110d", color: GOLD_HI, fontSize: 12 }}>Back to {charLevel}</button>
            <button type="button" className="wf-btn" onClick={() => setCharLevel(preview)} style={{ padding: "3px 10px", borderRadius: 6, border: `1px solid ${GOLD}`, background: "linear-gradient(180deg,#7a1a12,#3d0c08)", color: GOLD_HI, fontSize: 12 }}>Set {charName} to {preview}</button>
          </div>
        ) : null}
        <TalentPlanner buildKey={buildKey} setBuildKey={setBuildKey} level={level} setLevel={setLevel} pathSpec={pathSpec} setPathSpec={setPathSpec} />
        {buildKey.indexOf("enh") === 0 ? (
          <BulletList items={PL.talents_enh_bullets} />
        ) : null}
        {buildKey === "aff_lvl" || buildKey === "aff_icy" || buildKey === "aff_raid" ? (
          <Callout tone={PL.talents_level60.tone} lead={PL.talents_level60.lead}>{PL.talents_level60.text}</Callout>
        ) : null}
        {buildKey === "demo_lvl" || buildKey === "demo_raid" || buildKey === "path" ? (
          <Callout tone={PL.talents_brand.tone} lead={PL.talents_brand.lead}>{PL.talents_brand.text}</Callout>
        ) : null}
      </Section>

      <Section heading="Rotations" id="rotations" caption="Questing vs dungeon priorities per spec, as icon strips. Sources and dates under each.">
        <RotationBoard lvV={lvV} lvC={lvC} />
      </Section>

      <Section heading="Naga V2 Pro binds" id="naga" caption="From your notes: 6-button plate, Synapse Standard mode, Hypershift off. Shift+Naga is the second layer, so 12 combat binds.">
        <Segmented options={use12 && nagaSpec !== "enh" ? [{ value: "aff", label: "Spec 1 · Affliction" }, { value: "demo", label: "Spec 2 · Demonology" }, { value: "enh", label: "Enhancement" }] : specOptions} value={nagaSpec} onChange={(v: string) => { setNagaSpec(v); setStagePick(null); }} />
        <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", padding: "8px 12px", borderRadius: 8, border: `1px solid ${use12 && !reached12 ? ORANGE : "#4a3d22"}`, background: use12 && !reached12 ? "rgba(255,128,0,.08)" : "rgba(0,0,0,.25)", color: INK, fontSize: 13 }}>
          <Icon icon={nagaSpec === "enh" ? "classicon_shaman" : "classicon_warlock"} size={24} ring={nagaColor} />
          <span style={{ flex: "1 1 260px" }}>{reached12 ? `${nagaWho} is level ${nagaLv}: 12-button plate (it starts at ${n12.from}).` : prev12 ? `Preview only. ${nagaWho} is level ${nagaLv}; this 12-button layout is for ${n12.from}+. Keep the 6-button binds in game until then.` : `${nagaWho} is level ${nagaLv}: 6-button plate. The 12-button layout starts at ${n12.from}.`}</span>
          {reached12 ? null : (
            <button type="button" className="wf-btn" aria-pressed={prev12} onClick={() => setPrev12(!prev12)} style={{ padding: "4px 12px", borderRadius: 6, border: `1px solid ${prev12 ? ORANGE : GOLD}`, background: prev12 ? "rgba(255,128,0,.18)" : "linear-gradient(180deg,#7a1a12,#3d0c08)", color: prev12 ? ORANGE : GOLD_HI, fontSize: 12, fontWeight: 700 }}>{prev12 ? `Back to ${nagaWho}'s 6-button` : `Preview 12-button (${nagaWho})`}</button>
          )}
        </div>
        {use12 ? null : <Segmented options={spec.stages.map((s: Stage) => ({ value: s.id, label: s.label }))} value={stage.id} onChange={(v: string) => setStagePick(v)} />}
        {use12 ? null : <Text>{stagePick ? `Manual pick. Change ${nagaSpec === "enh" ? "Vorgash's" : "Corvin's"} level to go back to automatic.` : `Automatic for ${nagaSpec === "enh" ? "Vorgash" : "Corvin"} at level ${nagaLv}${nagaSpec === "enh" ? ` (Stormstrike at ${ssLv} in the Icy Veins order)` : nagaSpec === "demo" ? ` (Demonic Brand at ${brandLv} in the Icy Veins order)` : wrackLv < 99 ? ` (Wrack layout from ${wrackLv}, when the Icy Veins order takes Wrack)` : " (the Wrack layout stays manual: Wrack isn't in Corvin's Affliction leveling build)"}.`}</Text>}
        {use12 ? <NagaPad12 layout={n12} fkeys={spec.fkeys} color={nagaColor} preview={!reached12} /> : <NagaPad base={stage.base} shift={spec.shift} fkeys={spec.fkeys} color={nagaColor} />}
        {use12 ? (
          <Callout tone={PL.naga_when_to_swap.tone} lead={PL.naga_when_to_swap.lead}>{PL.naga_when_to_swap.text}</Callout>
        ) : null}
        <PreLine lead="12-button layouts (32+ / 40+) and binds past level 30:" mark="notes" />
        {use12 ? <Steps steps={SETUP12} /> : null}
        {use12 ? null : <Steps steps={PL.naga_setup6} />}
        <Text>{use12 ? "Setup steps above are from the Class Hub note (12-button plate). Per-spec binds are from each class note's 12-button layout section." : "The 12-button plate takes over at 32 for Vorgash and 40 for Corvin (Spec 1 Affliction and Spec 2 Demonology). Use the preview button to see it early."}</Text>
      </Section>

      <Section heading="Professions" id="profs" caption="Pick a character, then a profession. Skill uses the same numbers as the character cards; − / + or drag. Training thresholds warn when the character level is too low. Legacy points at 150, 225 and 300 in each crafting profession, once per account.">
        <ProfessionWindow skills={st.sk} setSkillFor={setSkill} lvV={lvV} lvC={lvC} />
        <Text>{PL.profs_note_skinning.text}</Text>
        <Text>{PL.profs_note_tailoring.text}</Text>
        <Text>{PL.profs_note_trainers.text}</Text>
        <Text>{PL.profs_note_slider.text}</Text>
      </Section>

      <Section heading="Gear and dungeons" id="gear" caption="Best pick per slot from your notes. Stats past level 30 stay hidden until an item drops on the server.">
        <Segmented options={[{ value: "lock", label: "Corvin (Warlock) · Main" }, { value: "sham", label: "Vorgash (Shaman) · Alt" }]} value={gearChar} onChange={(v: string) => setGearChar(v)} />
        <GearSheet who={gearChar === "lock" ? "lock" : "sham"} lv={gearChar === "lock" ? lvC : lvV} ck={st.ck} toggle={toggle} />
        <Table columns={["Cleared", "Dungeon", "Levels", "Vorgash", "Preset (Vorgash)", "Corvin"]} rows={DUNGEONS.map((r: string[], i: number) => [
          <span style={{ display: "inline-flex", gap: 6, alignItems: "center", fontSize: 11 }}><TickBox on={!!st.ck[`dv${DKEYS[i]}`]} onClick={() => toggle(`dv${DKEYS[i]}`)} small color={SHAMAN} />V<TickBox on={!!st.ck[`dc${DKEYS[i]}`]} onClick={() => toggle(`dc${DKEYS[i]}`)} small color={WARLOCK} />C</span>,
          r[0], dunTop(r[1]) > 30 ? <span style={{ display: "inline-flex", flexDirection: "column", gap: 2 }}>{r[1]}<span className="wf-pre wf-pre-sm" title={`${PRE_LABEL} · ${PRE_MARKS.notes[1]}`}>31+ pre-launch</span></span> : r[1], dunCell(r[2]), <PresetCell i={i} open={presetOpen.indexOf(i) >= 0} onToggle={togglePreset} />, dunCell(r[3])])} />
        <PreLine lead="Dungeon rows and totem presets marked 31+:" mark="notes" />
        <PresetPanel open={presetOpen} setOpen={setPresetOpen} />
        <Text>{PL.gear_raid_preview.text}</Text>
        <PreLine lead="Tier 1 and raid loot:" mark="datamined" />
      </Section>

      <Section heading="Macros" id="macros" caption="Spell-book cards: copy, check length (255 max) and open “What it does”. NEW = added from Forever sources; FIXED = corrected from v1.">
        <MacroBook lvV={lvV} lvC={lvC} />
        <Text>{PL.macros_skip.text}</Text>
      </Section>

      <Section heading="Addons" id="addons">
        <Section heading="Installed (14), all untested until launch">
          <Table columns={["Addon", "Version", "What it does", "Status"]} rows={INSTALLED.map((r: string[]) => [r[0], r[1], r[2], <Status tone="neutral">Installed · untested</Status>])} />
          <Text>{PL.addons_installed_note.text}</Text>
        </Section>
        <Section heading="Recommended to try: Shaman">
          <LinkCards links={PL.addons_links_shaman} />
        </Section>
        <Section heading="Recommended to try: Warlock">
          <LinkCards links={PL.addons_links_warlock} />
        </Section>
        <Section heading="Recommended to try: both">
          <LinkCards links={PL.addons_links_both} />
          <Text>{PL.addons_install_note.text}</Text>
        </Section>
      </Section>

      <Section heading="Progress tracker" id="progress" caption="Tick items as you go. Saving depends on the viewer: the badge below says whether it works here.">
        <SavePanel storeOk={storeOk} code={code} onImport={importCode} onReset={resetAll} />
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 12, marginTop: 12 }}>
          {[...PROGRESS].sort((a: { heading: string }, b: { heading: string }) => progRank(a) - progRank(b)).map((g: { heading: string; items: Tick[] }) => (
            <div key={g.heading} style={{ padding: 10, borderRadius: 10, border: "1px solid #4a3d22", background: "linear-gradient(180deg,#1a1712,#0d0c0a)" }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontFamily: SERIF, color: GOLD_HI, fontSize: 15, marginBottom: 4 }}><span>{g.heading}</span><span style={{ fontSize: 12, color: MUTED }}>{g.items.filter((t: Tick) => st.ck[t.id]).length}/{g.items.length}</span></div>
              {g.items.map((t: Tick) => <TickBox key={t.id} on={!!st.ck[t.id]} onClick={() => toggle(t.id)} text={t.text} meta={t.meta} />)}
            </div>
          ))}
        </div>
      </Section>
    </Page>
  );
}
